#include "Aevrynd/ReplicationWorldAdapter3D.h"
#include <algorithm>
#include <cmath>
#include <cstdlib>
#include <limits>
#include <stdexcept>

namespace Aevrynd {
bool ReplicatedSceneRegistry3D::SpawnAtomic(std::span<const std::pair<NetworkEntityId3D,SceneEntityDefinition3D>> values,WorldOrigin3D origin){std::set<NetworkEntityId3D> unique;std::vector<SceneEntityDefinition3D> defs;defs.reserve(values.size());for(const auto&[id,definition]:values){if(!id||entities_.contains(id)||!unique.insert(id).second||!definition.transform)return false;auto value=definition;GlobalPosition3D global{};if(!ToGlobalPosition3D(value.transform->value.position,origin,global))return false;defs.push_back(std::move(value));}std::vector<SceneEntity3D> created;if(!scene_.CreateBatchAtomic(defs,created))return false;try{for(std::size_t i=0;i<values.size();++i){GlobalPosition3D global{};if(!ToGlobalPosition3D(defs[i].transform->value.position,origin,global))std::terminate();entities_.emplace(values[i].first,ReplicatedSceneState3D{created[i],global,global,0});}}catch(...){scene_.DestroyBatchAtomic(created);for(const auto&[id,value]:values)(void)value,entities_.erase(id);return false;}return true;}
bool ReplicatedSceneRegistry3D::DespawnAtomic(std::span<const NetworkEntityId3D>ids){std::vector<SceneEntity3D> local;local.reserve(ids.size());for(auto id:ids){auto found=entities_.find(id);if(found==entities_.end())return false;local.push_back(found->second.entity);}if(!scene_.DestroyBatchAtomic(local))return false;for(auto id:ids)entities_.erase(id);return true;}
bool ReplicatedSceneRegistry3D::Apply(NetworkEntityId3D id,GlobalPosition3D position,std::uint64_t tick,WorldOrigin3D origin){auto found=entities_.find(id);if(found==entities_.end()||tick<=found->second.tick||!NormalizeGlobalPosition3D(position))return false;Vec3 local{};if(!ToLocalPosition3D(position,origin,local))return false;auto*transform=scene_.Transform(found->second.entity);if(!transform)return false;auto next=*transform;next.value.position=local;if(!scene_.SetTransform(found->second.entity,next))return false;found->second.previous=found->second.current;found->second.current=position;found->second.tick=tick;return true;}
std::optional<ReplicatedSceneState3D> ReplicatedSceneRegistry3D::Query(NetworkEntityId3D id)const{auto found=entities_.find(id);if(found==entities_.end())return{};return found->second;}
void ReplicatedSceneRegistry3D::Clear(){std::vector<SceneEntity3D> local;for(const auto&[id,state]:entities_)(void)id,local.push_back(state.entity);if(!local.empty())scene_.DestroyBatchAtomic(local);entities_.clear();}
ReplicationChunkInterest3D::ReplicationChunkInterest3D(ReplicationInterestSettings3D value):settings_(value){if(value.loadRadius<0||value.retainRadius<value.loadRadius||!std::isfinite(value.chunkSize)||value.chunkSize<=0)throw std::invalid_argument("Invalid replication interest settings");}
bool ReplicationChunkInterest3D::Update(GlobalPosition3D observer,ReplicationInterestDelta3D&delta){if(!NormalizeGlobalPosition3D(observer)||epoch_==(std::numeric_limits<std::uint64_t>::max)())return false;const long double gx=static_cast<long double>(observer.chunk.x)*32+observer.offset.x,gz=static_cast<long double>(observer.chunk.z)*32+observer.offset.z;const long double cx=std::floor(gx/settings_.chunkSize),cz=std::floor(gz/settings_.chunkSize);const auto low=(std::numeric_limits<int>::min)()+settings_.retainRadius,high=(std::numeric_limits<int>::max)()-settings_.retainRadius;if(cx<low||cx>high||cz<low||cz>high)return false;const int x=int(cx),z=int(cz);std::set<std::pair<int,int>> next;for(const auto&chunk:chunks_){const auto dx=std::llabs(std::int64_t(chunk.first)-x),dz=std::llabs(std::int64_t(chunk.second)-z);if((std::max)(dx,dz)<=settings_.retainRadius)next.insert(chunk);}for(int dz=-settings_.loadRadius;dz<=settings_.loadRadius;++dz)for(int dx=-settings_.loadRadius;dx<=settings_.loadRadius;++dx)next.emplace(x+dx,z+dz);delta={++epoch_,{}, {}};for(const auto&v:next)if(!chunks_.contains(v))delta.entered.push_back({v.first,v.second});for(const auto&v:chunks_)if(!next.contains(v))delta.left.push_back({v.first,v.second});chunks_=std::move(next);view_.clear();for(auto[xv,zv]:chunks_)view_.push_back({xv,zv});return true;}
DurableMutationAuthority3D::DurableMutationAuthority3D(WorldChunkDeltaStore3D&s,IDurableMutationTarget3D&t,DurableMutationAuthoritySettings3D value):store_(s),target_(t),settings_(value){if(!value.sessionEpoch||!value.maximumPending||!value.maximumCompleted)throw std::invalid_argument("Invalid mutation authority settings");}
DurableMutationAuthority3D::~DurableMutationAuthority3D(){closed_=true;Poll();/* 中文：未完成IO不呼叫Abort，避免磁碟稍後durable卻回滾gameplay的矛盾。 */}
bool DurableMutationAuthority3D::Submit(ReplicationMutationRequest3D request,WorldChunkDeltaSnapshot3D current,std::uint64_t serverTick){if(closed_){++stats_.rejected;return false;}const auto key=std::pair{request.clientId,request.clientRequestId};if(auto duplicate=dedup_.find(key);duplicate!=dedup_.end()){if(completed_.size()>=settings_.maximumCompleted){++stats_.rejected;return false;}completed_.push_back(duplicate->second);++stats_.duplicates;stats_.completed=completed_.size();return true;}if(std::ranges::any_of(pending_,[&](const auto&value){return value.second.request.clientId==request.clientId&&value.second.request.clientRequestId==request.clientRequestId;})){++stats_.duplicates;return true;}if(request.sessionEpoch!=settings_.sessionEpoch||!request.clientId||!request.clientRequestId||pending_.size()>=settings_.maximumPending||completed_.size()+pending_.size()>=settings_.maximumCompleted){++stats_.rejected;return false;}if(current.key!=request.key||current.lastSequence==(std::numeric_limits<std::uint64_t>::max)()||!current.durableGeneration||current.durableGeneration==(std::numeric_limits<std::uint64_t>::max)()||nextIo_==(std::numeric_limits<std::uint64_t>::max)()){++stats_.rejected;return false;}DurableMutationAuthorizationContext3D context{settings_.sessionEpoch,serverTick,request.clientId,request.key,current.durableGeneration,current.base.contentRevision};if(!settings_.authorize||!settings_.authorize(request,context)){++stats_.unauthorized;++stats_.rejected;return false;}request.operation.sequence=++current.lastSequence;request.operation.serverTick=serverTick;request.operation.dirtyGeneration=current.durableGeneration+1;if(!request.operation.operationId.high&&!request.operation.operationId.low)request.operation.operationId=DeriveStableObjectId3D(request.key.world,request.key.chunk,current.lastSequence,9,request.clientRequestId);current.durableGeneration=request.operation.dirtyGeneration;current.operations.push_back(request.operation);const auto io=nextIo_++;if(!target_.Prepare(io,current)){target_.Abort(io);++stats_.rejected;return false;}if(!store_.EnqueueSave(io,settings_.sessionEpoch,current)){target_.Abort(io);++stats_.rejected;return false;}pending_.emplace(io,Pending{request,std::move(current),io});++stats_.submitted;stats_.pending=pending_.size();return true;}
void DurableMutationAuthority3D::Poll(){WorldDeltaSaveResult3D saved;while(store_.TryPopSave(saved)){auto found=pending_.find(saved.requestId);if(found==pending_.end()||saved.epoch!=settings_.sessionEpoch)continue;auto pending=std::move(found->second);pending_.erase(found);ReplicationMutationReceipt3D receipt{settings_.sessionEpoch,pending.request.clientRequestId,pending.request.operation.serverTick,pending.snapshot.lastSequence,pending.request.clientId,saved.durable,saved.durable,pending.request.operation.operationId};if(saved.durable){target_.Commit(pending.ioId,pending.snapshot);++stats_.durable;++stats_.committed;}else{target_.Abort(pending.ioId);++stats_.saveFailures;}const auto key=std::pair{receipt.clientId,receipt.clientRequestId};dedup_[key]=receipt;dedupOrder_.push_back(key);while(dedupOrder_.size()>settings_.maximumCompleted){dedup_.erase(dedupOrder_.front());dedupOrder_.pop_front();}completed_.push_back(receipt);stats_.pending=pending_.size();stats_.completed=completed_.size();}}
bool DurableMutationAuthority3D::Close(){closed_=true;Poll();stats_.closed=true;return pending_.empty();}
bool DurableMutationAuthority3D::TryPopReceipt(ReplicationMutationReceipt3D&value){if(completed_.empty())return false;value=completed_.front();completed_.pop_front();stats_.completed=completed_.size();return true;}
}
